<?php

declare(strict_types=1);

namespace Notification\Application\Command\Webhook;

use Shared\Application\Audit\AuditableCommand;
use Shared\Application\Audit\AuditAction;
use Shared\Application\Audit\AuditContext;
use Shared\Application\Audit\Target;
use Shared\Application\Security\RevealsSecret;

/**
 * A webhook of the team (`team.channels.manage`), its secret generated by the UI and shown once, stored encrypted. Audited on the team; never the URL (it may carry a token of the receiver) nor the secret.
 */
final readonly class RegisterWebhook implements AuditableCommand, RevealsSecret
{
    public function __construct(public string $webhookId, public string $teamId, public string $name, public string $url, #[\SensitiveParameter] public string $plainSecret)
    {
    }

    public function auditAction(): AuditAction
    {
        return AuditAction::named('notification.register_webhook', ['webhook_id']);
    }

    public function auditTarget(): Target
    {
        return Target::of('team', $this->teamId);
    }

    public function auditContext(): AuditContext
    {
        return AuditContext::for($this->auditAction(), ['webhook_id' => $this->webhookId]);
    }
}
